import React,{useEffect,useMemo,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {BrowserRouter,NavLink,Route,Routes,Link,useNavigate,useSearchParams,useLocation} from 'react-router-dom';
import {Sun,Menu,X,ArrowRight,Heart,Flower2,BookOpen,Users,CalendarDays,MessageCircle,ShieldCheck,Star,Clock,MapPin,Phone,Mail,ChevronRight,Sparkles,Leaf,Send,LogIn,LogOut,ClipboardList,NotebookPen,HandHeart,Lightbulb,Sprout} from 'lucide-react';
import {supabase,isBackendReady} from './lib/supabase';
import './styles.css';

const team=[['Roxanne Rea C. Barlongo','Founder','The heart behind Liwayway’s vision'],['May Lyn R. Isidro','Manager','Keeping every detail thoughtful and welcoming'],['Jamaica May H. Nobleza','Healthcare Staff','A caring presence throughout the journey'],['Hasnor A. Karim','System Manager','Building a smoother digital experience']];
const services=[['Bukang Liwayway','Before the light session','Just like the sunrise, healing does not happen all at once; it begins with a light of understanding. Bukang Liwayway is your first step before counseling. Complete registration, an initial assessment, and an emotional check-in so your therapist can better understand your current feelings, personal concerns, and the kind of support you may need. After the assessment, you may select your preferred mental health professional and request a session schedule.','sunrise'],['Liwanag ng Araw','During the light session','Sometimes, clarity begins when feelings are brought into the light. Liwanag ng Araw is the main counseling session where you can connect with mental health professionals and talk about concerns you may be experiencing. Whether you are dealing with emotional difficulties, relationship concerns, or personal struggles, it provides a space where you can be heard, understood, and guided toward positive steps forward.','sun'],['Takipsilim','After the light session','When the sun sets, the day leaves its lessons behind; so does every counseling session. Takipsilim is your post-counseling space for continued growth. After your session, complete follow-up assessments and explore therapeutic activities recommended by your counselor. These activities help you reflect on your experiences, recognize emotional changes, practice healthy coping strategies in daily life, monitor your progress, and identify areas where you may need further support.','sunset'],['Tala at Saloobin','Light journal','Some things are lighter to express when you write them down. Tala at Saloobin is your personal digital journal where you can freely express your thoughts, emotions, and experiences. Write a letter, document your everyday feelings, or put into words the things you have been keeping to yourself. Your entries are private, and you have control over what you choose to share.','journal']];
const eventsFallback=[{id:'e1',title:'Lightalk: Understanding Emotional Well-being',event_date:'2026-12-05',description:'A welcoming conversation about emotional well-being, everyday stress, and asking for support.',event_type:'Webinar'},{id:'e2',title:'Kapwa: A Circle of Support',event_date:'2026-12-12',description:'A guided community conversation centered on listening, empathy, and connection.',event_type:'Community'},{id:'e3',title:'Gentle Habits Workshop',event_date:'2027-01-09',description:'Small, practical ways to make room for rest, reflection, and self-kindness.',event_type:'Workshop'}];
function Brand({showTagline=false}){return <Link className="brand" to="/"><img className="brand-logo" src="data:image/webp;base64," alt="Liwayway logo"/><span><b>liwayway</b>{showTagline&&<small>Just like the sunrise, healing does not happen all at once; it begins with a light of understanding.</small>}</span></Link>}
function Header(){const[open,setOpen]=useState(false);const links=[['Home','/'],['About','/about'],['Behind Liwayway','/behind'],['Services','/services'],['Shared Liwayway','/shared'],['Steps','/steps'],['Events','/events'],['Liwayway Space','/dashboard']];return <header className="header"><div className="nav-wrap"><Brand/><nav className={open?'nav open':'nav'}>{links.map(([t,p])=><NavLink key={p} to={p} end={p==='/'} onClick={()=>setOpen(false)}>{t}</NavLink>)}<Link className="nav-cta" to="/login" onClick={()=>setOpen(false)}>Get started <ArrowRight size={15}/></Link></nav><button className="menu-btn" onClick={()=>setOpen(!open)} aria-label="Toggle menu">{open?<X/>:<Menu/>}</button></div></header>}
function Footer(){return <footer className="footer"><div className="footer-main"><div><Brand showTagline/><p className="muted">A little light, a little hope, and a gentler space to begin again.</p></div><div><b>Explore</b><Link to="/about">About Liwayway</Link><Link to="/services">Our services</Link><Link to="/events">Calendar of events</Link></div><div><b>Reach out</b><a href="mailto:liwaywaycounseling@gmail.com">liwaywaycounseling@gmail.com</a><a href="tel:2222">Telephone: 2222</a><span>OLFU PTRB, Quezon City</span></div></div><div className="footer-bottom"><span>© {new Date().getFullYear()} Liwayway. A space for care and connection.</span><span>For urgent support in the Philippines: NCMH Crisis Hotline 1553 or 1800-1888-1553.</span></div></footer>}
function ScrollToTop(){const location=useLocation();useEffect(()=>{window.scrollTo(0,0);},[location.pathname,location.search]);return null;}
function Shell({children}){return <><ScrollToTop/><Header/><main>{children}</main><Footer/></>}
function Eyebrow({children}){return <div className="eyebrow"><span/> {children}</div>}
function SectionTitle({eyebrow,title,copy}){return <div className="section-title"><Eyebrow>{eyebrow}</Eyebrow><h2>{title}</h2>{copy&&<p>{copy}</p>}</div>}
function Hero(){return <><section className="hero"><div className="hero-copy"><Eyebrow>A GENTLER WAY FORWARD</Eyebrow><h1>Just like the sunrise, healing does not happen all at once; it begins with a light of understanding.</h1><p>Whatever today feels like, you deserve a space where you can pause, be heard, and find your way forward — one small step at a time.</p><div className="hero-actions"><Link className="btn btn-primary" to="/login">Get started <ArrowRight size={17}/></Link><Link className="btn btn-quiet" to="/about">Get to know us</Link></div><div className="hero-note"><span className="avatar-dots"><i/><i/><i/></span><span>A space for understanding, care, and connection</span></div></div><div className="hero-art"><div className="sun-disc"><div className="sun-core"><Sun size={100} strokeWidth={1.1}/></div></div><div className="art-leaf leaf-one"><Leaf size={78}/></div><div className="art-leaf leaf-two"><Flower2 size={55}/></div><div className="art-note note-one">you are allowed<br/>to begin again</div><div className="art-note note-two">one day at a time ✿</div><div className="art-ground"/></div></section><div className="trust-strip"><span><Heart/> A kinder first step</span><span><ShieldCheck/> Your privacy matters</span><span><Sparkles/> Room to grow at your pace</span></div></>}
function Home(){return <><Hero/><section className="section intro-grid"><div><Eyebrow>WELCOME TO LIWAYWAY</Eyebrow><h2>Some days, the bravest thing is simply <em>beginning.</em></h2></div><div><p>Liwayway is a welcoming digital space for emotional well-being, learning, and community. Here, you can explore helpful resources, discover ways to connect, and take your next step at a pace that feels right.</p><Link className="text-link" to="/about">A little more about us <ArrowRight size={16}/></Link></div></section><section className="section tinted"><SectionTitle eyebrow="THE LIWAYWAY JOURNEY" title="A little light at every step" copy="From your first hello to the moments of reflection that follow, each part of the journey is designed to feel clear and considered."/><div className="service-grid">{services.map((s,i)=><article className="service-card" key={s[0]}><div className={'icon-bubble bubble-'+i}>{[<SunriseIcon/>,<Sun/>,<Flower2/>,<NotebookPen/>][i]}</div><small>{s[1]}</small><h3>{s[0]}</h3><p>{s[2]}</p><Link to="/services">Explore this step <ArrowRight size={15}/></Link></article>)}</div></section><section className="section split-feature"><div className="feature-illustration"><div className="feature-circle"><BookOpen size={65}/></div><span className="floating flower">✿</span><span className="floating sparkle">✧</span></div><div><Eyebrow>GROW AT YOUR OWN PACE</Eyebrow><h2>There is no one right way to <em>heal or grow.</em></h2><p>Find gentle reads, guided activities, shared conversations, and small reminders that you do not have to figure everything out all at once.</p><Link className="btn btn-outline" to="/steps">Find your next step <ArrowRight size={16}/></Link></div></section><section className="quote-band"><span>“</span><p>Even the softest sunrise changes the shape of the day.</p><small>— A Liwayway reminder</small></section><EventsPreview/></>}
function SunriseIcon(){return <Sun size={27}/>}
function About(){return <><PageHero tag="ABOUT LIWAYWAY" title={<>A little light for the <em>journey ahead.</em></>} text="Liwayway is built on the belief that every person deserves to be heard, understood, and supported. We aim to make mental health information easier to approach, encourage open conversations, and offer gentle pathways for reflection, learning, and personal growth."/><section className="section two-col"><div><Eyebrow>OUR STORY</Eyebrow><h2>Every sunrise begins with a little <em>light.</em></h2></div><div><p>Liwayway means “first light,” the gentle light that comes before the sun fully rises. It is an online counseling platform concept that offers accessible and compassionate mental health support, representing the beginning toward healing. Like the first light of dawn, it does not erase the darkness all at once; it simply makes room for hope to begin.</p><p>Liwayway began with a simple but meaningful idea: everyone deserves to be heard, understood, and supported, especially during their darkest moments. Many individuals silently struggle with stress, anxiety, emotional difficulties, and other mental health challenges. Some are afraid to speak up because they fear being judged, misunderstood, or ignored. This inspired the idea of creating a platform where people can feel safe expressing themselves and seeking the support they deserve.</p><p>The idea behind Liwayway came from a desire to make mental health awareness more accessible and to remind people that asking for help is not a sign of weakness. The goal is to build more than just a website: a supportive space where individuals can find information, guidance, encouragement, and access to mental health support.</p><p>As the vision developed, the name Liwayway was chosen because it means first light. It represents hope, guidance, and the possibility of finding strength even during difficult times. Just as sunrise brings brightness to darkness, Liwayway hopes to bring comfort and encouragement to those who feel lost or alone.</p><p>Today, Liwayway continues to stand for understanding, compassion, acceptance, and hope. Through mental health resources, counseling information, well-being programs, and professional support, the platform aims to remind everyone that no one has to face their struggles alone.</p></div></section><section className="section tinted"><SectionTitle eyebrow="WHAT GUIDES US" title="The values behind every little step" copy="Our values shape the way we listen, share information, and build a space where people feel respected."/><div className="values-grid">{[['L','Love and Compassion','Show genuine care, kindness, and understanding toward those facing mental and emotional struggles.'],['I','Inclusivity','Welcome everyone regardless of their background, experiences, or personal struggles. Everyone deserves to feel accepted and supported.'],['W','Well-being','Promote the importance of maintaining good mental, emotional, and psychological health.'],['A','Acceptance',"Embrace every individual's feelings and experiences without judgment, stigma, or discrimination."],['Y','Yearning for Growth','Encourage individuals to grow, learn, and develop themselves through continuous self-improvement.'],['W','Warmth','Create a caring and welcoming environment where everyone feels comfortable, valued, and supported.'],['A','Awareness','Encourage mental health education and understanding to help break misconceptions and reduce stigma surrounding mental health.'],['Y','Your Journey Matters',"Respect and support each individual's unique journey toward healing, growth, and self-discovery."]].map(v=><div className="value-card" key={v[0]+v[1]}><b>{v[0]}</b><div><h3>{v[1]}</h3><p>{v[2]}</p></div></div>)}</div></section><section className="section mission-grid"><div className="mission-card"><span>OUR MISSION</span><h2>A safe space to be <em>heard.</em></h2><p>To provide a safe, welcoming, and supportive space where individuals can freely express their thoughts, emotions, and personal struggles without fear of judgment. Liwayway promotes mental health awareness, encourages emotional well-being, and connects individuals with proper guidance and support through understanding, compassion, and accessible mental health resources.</p></div><div className="mission-card peach"><span>OUR VISION</span><h2>A community where mental health is <em>valued and accepted.</em></h2><p>We envision a world where everyone feels safe to speak about their struggles, has access to the support they need, and is empowered to prioritize their mental well-being. Liwayway hopes to become a source of hope and encouragement, helping individuals find strength, healing, and light even during their darkest moments.</p></div></section></>}
function PageHero({tag,title,text}){return <section className="page-hero"><div className="page-hero-inner"><Eyebrow>{tag}</Eyebrow><h1>{title}</h1><p>{text}</p></div><div className="page-hero-sun"><Sun size={84}/></div></section>}
function Behind(){return <><PageHero tag="BEHIND LIWAYWAY" title={<>The people and purpose behind the <em>light.</em></>} text="Behind Liwayway is a team with different responsibilities and a shared purpose: to make this digital space welcoming, informative, organized, and grounded in compassion. Each role contributes to the planning, care, and continued improvement of the project."/><section className="section two-col"><div><Eyebrow>BEHIND THE LIWAYWAY</Eyebrow><h2>Care begins with people who <em>care.</em></h2></div><div><p>Liwayway recognizes that mental health and well-being are shaped by many parts of a person's life. By bringing together perspectives from psychiatry, psychology, psychometrics, and guidance counseling, the project highlights the value of informed, compassionate, and respectful support. Each discipline contributes a different perspective, from understanding mental health concerns to assessment, guidance, and personal development.</p><p>The people behind Liwayway also work across planning, coordination, healthcare-related content, and system management. Together, these roles help shape a digital environment where visitors can learn about available resources, reflect on their experiences, and find clear next steps. Information on this website is educational and does not replace individualized care from a qualified professional.</p></div></section><section className="section tinted"><SectionTitle eyebrow="THE LIWAYWAY TEAM" title="Different roles, one shared purpose" copy="Each member contributes a different skill and responsibility, from guiding the project's direction and coordinating its work to supporting healthcare-related content and maintaining the digital system. Their shared goal is to help make the Liwayway experience thoughtful, accessible, and easy to navigate."/><div className="team-grid">{team.map((m,i)=><article className="team-card" key={m[0]}><div className={'team-avatar av-'+i}>{['R','M','J','H'][i]}<span>✿</span></div><div className="team-info"><small>{m[1]}</small><h3>{m[0]}</h3><p>{m[2]}</p></div></article>)}</div></section><section className="section professional-section"><div><Eyebrow>PROFESSIONAL PERSPECTIVES</Eyebrow><h2>Support shaped by <em>knowledge and care.</em></h2><p>Liwayway's content highlights the value of different mental health and guidance disciplines, including psychiatry, psychology, psychometrics, and guidance counseling.</p></div><div className="professional-list">{[['Psychiatrist','Doctor of Medicine (M.D.); board-certified psychiatrist; specializes in mood disorders, anxiety, and other psychiatric conditions; 8 years of mental health care experience.'],['Psychologist (RPsy)','Ph.D. in Clinical Psychology; licensed psychologist; specializes in emotional difficulties, stress management, and behavioral concerns; 7 years of psychological practice.'],['Psychometrician (RPm)','Bachelor’s Degree in Psychology; registered psychometrician; trained in psychological testing and assessment; 3 years of assessment experience.'],['Guidance Counselor','Master’s Degree in Guidance and Counseling; registered guidance counselor; specializes in personal development, academic concerns, and emotional support; 5 years of counseling experience.']].map(x=><div><span><Flower2 size={19}/></span><div><b>{x[0]}</b><small>{x[1]}</small></div><ChevronRight/></div>)}</div></section><section className="section tinted"><SectionTitle eyebrow="OUR SUPPORTING COMMUNITY" title="A shared commitment to mental health" copy="Mental health awareness grows stronger when schools, public institutions, community organizations, and supporters work together. These groups represent the wider network of advocates and resources that can help encourage education, reduce stigma, and make support more visible and accessible."/><div className="partner-grid">{[['Department of Health (DOH)','A potential public-sector partner for mental health awareness and accessible services.'],['National Center for Mental Health (NCMH)','A key national resource for mental health support and crisis assistance.'],['Non-governmental organizations','Community partners supporting advocacy, outreach, and mental health programs.'],['Private donors and corporate sponsors','Potential supporters helping sustain accessible awareness and community initiatives.']].map(x=><article className="partner-card"><b>{x[0]}</b><p>{x[1]}</p></article>)}</div></section></>}
function Services(){return <><PageHero tag="LIWAYWAY SERVICES" title={<>A journey made of <em>small steps.</em></>} text="Every individual's journey is different. Liwayway organizes its services around the moments before, during, and after a counseling session, while also providing a personal space for reflection. Explore each step below to understand what it involves and which form or activity belongs to it."/><section className="section service-detail-list">{services.map((s,i)=><article className="service-detail" key={s[0]}><div className={'detail-number dn-'+i}>0{i+1}</div><div><Eyebrow>{s[1]}</Eyebrow><h2>{s[0]}</h2><p>{s[2]}</p>{i===0?<><h3>Before your session</h3><ul><li><b>Registration Form:</b> Fill in your basic information, school email address, and account password to create an account. Review the Privacy Notice and provide your acknowledgment before proceeding.</li><li><b>Initial Assessment and Emotional Check-in:</b> Answer questions about your current feelings, emotional distress, changes in daily habits, personal concerns, how long you have experienced them, their effect on daily life, and the ways you usually cope.</li><li><b>Appointment Form:</b> After completing your assessment, select your preferred mental health professional, consultation type, date, time, format, and reason for requesting an appointment. Your submission is a request and is subject to confirmation.</li></ul><div className="service-actions"><Link className="text-link" to="/register">Registration <ArrowRight size={16}/></Link><Link className="text-link" to="/assessment">Initial assessment <ArrowRight size={16}/></Link><Link className="text-link" to="/appointment">Appointment form <ArrowRight size={16}/></Link></div></>:i===1?<><h3>Our counseling and psychological services</h3><ul><li><b>Individual Counseling:</b> A confidential space where you can openly discuss personal experiences, emotional difficulties, stress, anxiety, and other concerns. With professional guidance, you can better understand your emotions, recognize patterns in your thoughts and behavior, and explore healthier coping strategies.</li><li><b>Relationship Counseling:</b> A supportive service for individuals experiencing relationship difficulties, communication problems, interpersonal conflicts, or challenges in maintaining healthy connections. This service encourages better understanding, constructive communication, and healthier relationship patterns.</li><li><b>Personal Development Counseling:</b> An opportunity to explore your strengths, recognize areas for growth, and work toward meaningful personal goals. Through guided self-reflection, you can develop greater self-awareness, improve decision-making, and strengthen your ability to navigate everyday challenges.</li></ul><h3>What to expect during your session</h3><ol><li><b>Initial Connection:</b> Meet your assigned mental health professional, who will introduce the session, explain the process, and help establish a comfortable environment.</li><li><b>Sharing Your Concerns:</b> Talk about your thoughts, feelings, and experiences at your own pace. You are not pressured to disclose everything immediately.</li><li><b>Understanding Your Situation:</b> Explore your concerns, identify possible contributing factors, and gain a better understanding of your experiences.</li><li><b>Receiving Professional Guidance:</b> Receive appropriate guidance, insights, and possible strategies based on your needs.</li><li><b>Exploring Your Next Steps:</b> Discuss practical steps, recommendations, or possible follow-up sessions before concluding.</li></ol><Link className="text-link" to="/appointment">Request a session <ArrowRight size={16}/></Link></>:i===2?<><h3>Post-counseling assessment</h3><p>Answer the follow-up questionnaire based on your experience after your most recent counseling session. There are no right or wrong answers. Your responses can help you reflect on emotional changes, the strategies you have tried, and the areas you may want to continue working on.</p><h3>Therapist-recommended therapeutic activities</h3><ul><li>Guided journaling or writing your thoughts and feelings.</li><li>Breathing exercises, relaxation, and mindfulness practice.</li><li>Drawing, music, and other creative activities.</li><li>Walking or spending time outdoors.</li><li>Practicing coping strategies discussed during counseling.</li><li>Setting a manageable personal goal before the next session.</li></ul><h3>Coping progress monitoring</h3><p>Use follow-up reflections to notice changes in how you manage emotions, respond to personal challenges, express your thoughts, and practice activities that support your well-being. Progress may happen gradually; the purpose is to recognize meaningful steps and identify where further guidance may help.</p><Link className="text-link" to="/follow-up">Open post-counseling assessment <ArrowRight size={16}/></Link></>:<><h3>Your personal journal</h3><p>You may use guided prompts when you are unsure where to begin, save entries, revisit previous reflections, and edit or delete your writing. You do not have to write every day. Take your time and write whenever you feel ready.</p><Link className="text-link" to="/journal">Open your journal <ArrowRight size={16}/></Link></>}</div><div className={'detail-art da-'+i}>{[<SunriseIcon/>,<Sun/>,<Flower2/>,<NotebookPen/>][i]}</div></article>)}</section></>}
function Shared(){return <><PageHero tag="SHARED LIWAYWAY" title={<>A little light is brighter when <em>shared.</em></>} text="Liwayway creates opportunities to learn and connect through educational webinars and meaningful community outreach. Lightalk and Kapwa have different purposes, but both are rooted in care, understanding, and shared growth."/><section className="section shared-grid"><article className="shared-card"><div className="shared-icon si-0"><MessageCircle/></div><small>01 / LEARN TOGETHER</small><h2>Lightalk</h2><h4>Webinar sessions</h4><p>Lightalk is Liwayway's learning space for webinar sessions about mental health awareness, emotional well-being, self-understanding, healthy relationships, and practical ways of caring for ourselves. Each session is designed to share useful knowledge, encourage reflection, and make important conversations about mental health more approachable.</p><div className="resource-tags"><span>Mental health awareness</span><span>Emotional well-being</span><span>Self-care and coping</span></div><Link className="text-link" to="/events?type=lightalk">View Lightalk webinars <ArrowRight size={16}/></Link></article><article className="shared-card"><div className="shared-icon si-1"><Users/></div><small>02 / SERVE THE COMMUNITY</small><h2>Kapwa</h2><h4>Outreach programs</h4><p>Kapwa focuses on bringing care beyond the website and into the community. Through outreach programs, volunteer involvement, and partnerships, Kapwa aims to promote mental health awareness, extend kindness, and make supportive resources more accessible. It is an invitation to take part, lend a hand, and help create a more understanding community.</p><div className="resource-tags"><span>Community outreach</span><span>Volunteer opportunities</span><span>Mental health advocacy</span></div><a className="text-link" href="mailto:liwaywaycounseling@gmail.com?subject=Be%20Part%20of%20Kapwa%20-%20Volunteer">Be part of Kapwa <ArrowRight size={16}/></a></article><article className="shared-card"><div className="shared-icon si-2"><Star/></div><small>03 / SHARE YOUR VOICE</small><h2>Liwayway Reviews</h2><h4>Stories and reflections</h4><p>Your feedback helps us understand what feels helpful, what can be improved, and how the Liwayway website can become easier and more welcoming to use. Share your experience voluntarily and in your own words.</p><a className="text-link" href="/feedback">Leave feedback <ArrowRight size={16}/></a></article></section></>}
function Steps(){return <><PageHero tag="STEPS WITH LIWAYWAY" title={<>A little guidance for your <em>next step.</em></>} text="Tanglaw ng Kaalaman is Liwayway's help center. It provides instructions, mental health information, and articles for visitors who want to learn about mental health, explore helpful reading materials, or understand step by step how to use the Liwayway website."/><section className="section"><SectionTitle eyebrow="HOW TO USE THE WEBSITE" title="Your guide to finding your way around" copy="You may explore the public pages without signing in. To use personal features such as assessments, appointment requests, and your journal, create an account or sign in first."/><div className="service-grid">{[['01','Create your account','Choose Get Started and select Create an Account. Enter your full name, school email address, and password, confirm your password, review the Privacy Notice and Informed Consent, and acknowledge it before submitting your registration. After registering, follow the email confirmation instructions and sign in.'],['02','Explore the pages','Visit About Liwayway to learn about its background, mission, vision, and core values. The Behind Liwayway page introduces the mental health disciplines, project team, institution, and proposed supporters. Browse Services to understand each step of the Liwayway journey.'],['03','Begin with Bukang Liwayway','After signing in, complete the Initial Assessment and Emotional Check-in. Share only what you feel comfortable sharing. Then proceed to the separate Appointment Form to choose a preferred professional, consultation type, date, time, format, and reason for your request. Wait for confirmation of your requested schedule.'],['04','Continue with your Liwayway journey','Liwanag ng Araw describes the counseling session and what to expect. After a session, return to Takipsilim to complete the Post-Counseling Assessment and explore recommended activities. Use Tala at Saloobin for private journaling.'],['05','Learn and connect','Visit Shared Liwayway for Lightalk webinars and Kapwa community outreach information. Read the articles in Tanglaw ng Kaalaman, check the event calendar, and use Liwayway Reviews if you wish to share voluntary feedback.']].map(x=><article className="service-card" key={x[0]}><small>{x[0]} / YOUR GUIDE</small><h3>{x[1]}</h3><p>{x[2]}</p></article>)}</div><div className="section-actions"><Link className="text-link" to="/register">Create an account <ArrowRight size={16}/></Link><Link className="text-link" to="/privacy">Read the Privacy Notice <ArrowRight size={16}/></Link></div></section><section className="section tinted"><SectionTitle eyebrow="TANGLAW NG KAALAMAN" title={<>Mental health resources and <em>articles.</em></>} copy="Explore these recommended articles and research materials to learn more about mental health, emotional well-being, and online psychological support."/><div className="resources-grid"><article className="resource-card large"><div className="resource-icon"><BookOpen/></div><Eyebrow>ARTICLE 01 · MENTAL HEALTH AWARENESS</Eyebrow><h2>Mental Health and Well-being of Adolescents</h2><p>Learn about the mental health needs of adolescents, factors that can affect well-being, and why early support, understanding, and accessible services matter.</p><a className="text-link" href="https://www.who.int/news-room/fact-sheets/detail/adolescent-mental-health" target="_blank" rel="noreferrer">Read the WHO article <ArrowRight size={16}/></a></article><article className="resource-card"><div className="resource-icon"><Heart/></div><Eyebrow>ARTICLE 02 · DIGITAL SUPPORT</Eyebrow><h3>Online Counseling and Digital Mental Health Support</h3><p>Explore research discussing online counseling and the role of digital tools in making mental health support more accessible.</p><a className="text-link" href="https://pmc.ncbi.nlm.nih.gov/articles/PMC11380195/" target="_blank" rel="noreferrer">Read the research <ArrowRight size={16}/></a></article><article className="resource-card"><div className="resource-icon"><Sprout/></div><Eyebrow>ARTICLE 03 · AWARENESS</Eyebrow><h3>Mental Health Awareness and Removing Stigma</h3><p>Read about public understanding of mental health and efforts to address stigma and misconceptions.</p><a className="text-link" href="https://jamanetwork.com/journals/jamanetworkopen/fullarticle/2829229" target="_blank" rel="noreferrer">Read the article <ArrowRight size={16}/></a></article><article className="resource-card"><div className="resource-icon"><HandHeart/></div><Eyebrow>ARTICLE 04 · YOUNG PEOPLE</Eyebrow><h3>Online Mental Health Interventions for Young People</h3><p>Explore research on digital mental health interventions and support designed for young people.</p><a className="text-link" href="https://mental.jmir.org/2024/1/e46637" target="_blank" rel="noreferrer">Read the research <ArrowRight size={16}/></a></article><article className="resource-card"><div className="resource-icon"><BookOpen/></div><Eyebrow>ARTICLE 05 · ONLINE COUNSELING</Eyebrow><h3>Therapeutic Relationship in Online Counseling</h3><p>Learn about the therapeutic relationship and how connection and communication are considered in online counseling.</p><a className="text-link" href="https://pubmed.ncbi.nlm.nih.gov/38636207/" target="_blank" rel="noreferrer">Read the research <ArrowRight size={16}/></a></article></div></section><section className="section resources-grid"><article className="resource-card"><div className="resource-icon"><ShieldCheck/></div><Eyebrow>DATA PRIVACY AND CONSENT</Eyebrow><h3>Your information deserves care.</h3><p>Read how information entered into account features and forms is collected, used, stored, and protected, and understand your choices before proceeding.</p><Link className="text-link" to="/privacy">Read Privacy Notice &amp; Informed Consent <ArrowRight size={16}/></Link></article><article className="resource-card"><div className="resource-icon"><MessageCircle/></div><Eyebrow>FREQUENTLY ASKED QUESTIONS</Eyebrow><h3>Need a little clarity?</h3><p>Find answers about Liwayway, account registration, counseling services, other features, privacy, and reviews.</p><Link className="text-link" to="/faq">Explore all FAQs <ArrowRight size={16}/></Link></article><article className="resource-card"><div className="resource-icon"><Phone/></div><Eyebrow>CRISIS SUPPORT</Eyebrow><h3>Immediate help matters.</h3><p>Liwayway is not an emergency response service. If you or someone else is in immediate danger, contact local emergency services or the National Center for Mental Health Crisis Hotline.</p><b className="hotline">NCMH: 1553</b><small>1800-1888-1553</small></article></section></>}
function EventsPreview(){return <section className="section events-preview"><div><Eyebrow>UPCOMING MOMENTS</Eyebrow><h2>Make space for a little <em>connection.</em></h2><p>Explore community events and Lightalk learning sessions in separate calendars.</p><Link className="text-link" to="/events">See the full calendar <ArrowRight size={16}/></Link></div><div className="events-preview-lists"><div><h3>Other upcoming events</h3><EventList compact category="general"/></div><div><h3>Lightalk sessions</h3><EventList compact category="lightalk"/><Link className="text-link" to="/events?type=lightalk">Explore Lightalk <ArrowRight size={16}/></Link></div></div></section>}
function toEventDate(value){const s=String(value||'');return new Date(s.includes('T')?s:s.replace(' ','T').replace('+00','Z'));}
function EventList({compact=false,category='all'}){
 const[events,setEvents]=useState(eventsFallback);
 useEffect(()=>{if(!supabase)return;supabase.from('events').select('*').eq('is_published',true).order('starts_at',{ascending:true}).then(({data,error})=>{if(!error&&data?.length)setEvents(data)});},[]);
 const isLightalk=e=>/lightalk|webinar/i.test((e.title||'')+' '+(e.event_type||e.category||''));
 const visibleEvents=events.filter(e=>category==='lightalk'?isLightalk(e):category==='general'?!isLightalk(e):true);
 return <div className="event-list">{visibleEvents.length?visibleEvents.map((e,i)=><article className="event-row" key={e.id||i}><div className="event-date"><b>{toEventDate(e.starts_at||e.event_date).toLocaleDateString('en',{day:'2-digit'})}</b><small>{toEventDate(e.starts_at||e.event_date).toLocaleDateString('en',{month:'short'})}</small></div><div className="event-details"><small>{isLightalk(e)?'LIGHTALK · WEBINAR':'LIWAYWAY COMMUNITY EVENT'}</small><h3>{e.title}</h3>{!compact&&<p>{e.description}</p>}</div>{!compact&&<Link className="round-arrow" to={'/event-register?event='+e.id}><ArrowRight/></Link>}</article>):<p className="empty-state">{category==='lightalk'?'There are no published Lightalk webinar sessions at the moment. Please check back for updates.':'There are no other upcoming events published at the moment. Please check back for updates.'}</p>}</div>;
}
function Events(){const[params]=useSearchParams();const lightalkOnly=params.get('type')==='lightalk';return <><PageHero tag={lightalkOnly?'LIGHTALK WEBINARS':'CALENDAR OF EVENTS'} title={lightalkOnly?<>Learn and reflect with <em>Lightalk.</em></>:<>Gather, learn, and <em>grow together.</em></>} text={lightalkOnly?'Explore Liwayway webinar sessions focused on mental health awareness, emotional well-being, self-understanding, and practical ways of caring for ourselves.':'Explore upcoming Liwayway community events and Lightalk webinar sessions in their own dedicated sections.'}/>{lightalkOnly?<section className="section"><div className="events-heading"><div><Eyebrow>LIGHTALK · WEBINAR SESSIONS</Eyebrow><h2>Upcoming Lightalk webinars</h2></div><span className="calendar-label"><CalendarDays/> Liwayway calendar</span></div><EventList category="lightalk"/></section>:<><section className="section"><div className="events-heading"><div><Eyebrow>WHAT'S COMING UP</Eyebrow><h2>Other upcoming events</h2><p>Community activities, workshops, and shared moments beyond the Lightalk webinar series.</p></div><span className="calendar-label"><CalendarDays/> Liwayway calendar</span></div><EventList category="general"/></section><section className="section tinted"><div className="events-heading"><div><Eyebrow>LIGHTALK · WEBINAR SERIES</Eyebrow><h2>Upcoming Lightalk sessions</h2><p>Dedicated learning sessions for mental health awareness and emotional well-being.</p></div><Link className="text-link" to="/events?type=lightalk">View Lightalk calendar <ArrowRight size={16}/></Link></div><EventList category="lightalk"/></section></>}</>}
function AuthForm({mode='login'}){const[email,setEmail]=useState(''),[password,setPassword]=useState(''),[confirmPassword,setConfirmPassword]=useState(''),[name,setName]=useState(''),[message,setMessage]=useState(''),[busy,setBusy]=useState(false);const nav=useNavigate();async function submit(e){e.preventDefault();setMessage('');if(mode==='register'&&password!==confirmPassword){setMessage('Your passwords do not match.');return;}if(!supabase){setMessage('Account services are not connected yet. Please try again later.');return;}setBusy(true);const res=mode==='register'?await supabase.auth.signUp({email,password,options:{data:{full_name:name}}}):await supabase.auth.signInWithPassword({email,password});setBusy(false);if(res.error)setMessage(res.error.message);else if(mode==='register')setMessage('Please check your email for a confirmation link, then sign in.');else nav('/dashboard');}return <section className="form-page"><div className="form-aside"><div className="form-sun"><Sun size={65}/></div><Eyebrow>A GENTLE PLACE TO BEGIN</Eyebrow><h2>{mode==='register'?'Your next chapter starts with a hello.':'Welcome back to your space.'}</h2><p>Take things one step at a time. Your journey is your own.</p></div><form className="form-card" onSubmit={submit}><Eyebrow>{mode==='register'?'CREATE AN ACCOUNT':'SIGN IN'}</Eyebrow><h1>{mode==='register'?'Join Liwayway':'Welcome back'}</h1><p className="form-intro"> {mode==='register'?'Create an account to access your personal Liwayway features.':'Sign in to continue to your personal space.'}</p>{mode==='register'&&<Field label="Full name" value={name} onChange={setName} required/>}<Field label={'Email address'} type="email" value={email} onChange={setEmail} required/><Field label="Password" type="password" value={password} onChange={setPassword} required/>{mode==='register'&&<Field label="Confirm password" type="password" value={confirmPassword} onChange={setConfirmPassword} required/>}<label className="checkline consent-check"><input type="checkbox" required/><span>I have read the <a href="/privacy">Privacy Notice &amp; Informed Consent</a> and voluntarily agree to provide the information needed for this service. I understand this is not an emergency service.</span></label><button className="btn btn-primary full" disabled={busy}>{busy?'Please wait…':mode==='register'?'Create account':'Sign in'} <ArrowRight size={16}/></button>{message&&<p className="form-message">{message}</p>}<p className="form-switch">{mode==='register'?'Already have an account?':'New to Liwayway?'} <Link to={mode==='register'?'/login':'/register'}>{mode==='register'?'Sign in':'Create an account'}</Link></p></form></section>}
function Field({label,value,onChange,type='text',required=false,placeholder=''}){return <label className="field"><span>{label}</span><input type={type} value={value} onChange={e=>onChange(e.target.value)} required={required} placeholder={placeholder}/></label>}
function SelectField({label,value,onChange,options}){return <label className="field"><span>{label}</span><select value={value} onChange={e=>onChange(e.target.value)}>{options.map(o=><option>{o}</option>)}</select></label>}
function TextArea({label,value,onChange,placeholder}){return <label className="field"><span>{label}</span><textarea value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder} rows="4"/></label>}
function Appointment(){const[form,setForm]=useState({name:'',email:'',professional:'No preference',type:'Individual counseling',date:'',time:'',format:'Online',reason:''}),[msg,setMsg]=useState('');const upd=(k,v)=>setForm(p=>({...p,[k]:v}));async function submit(e){e.preventDefault();if(!supabase){setMsg('Appointment requests are temporarily unavailable. Please email liwaywaycounseling@gmail.com.');return;}const{data:{user}}=await supabase.auth.getUser();if(!user){setMsg('Please sign in or create an account before requesting an appointment.');return;}const{error}=await supabase.from('appointments').insert({user_id:user.id,preferred_name:form.name,email:form.email,professional_preference:form.professional,consultation_type:form.type,preferred_date:form.date,preferred_time:form.time,consultation_format:form.format,reason:form.reason,status:'pending'});setMsg(error?error.message:'Your appointment request has been submitted. You can review its status in your dashboard.');}return <FormLayout tag="REQUEST AN APPOINTMENT" title="A thoughtful first step." intro="Tell us a little about the session you are hoping for. You can share only what you are comfortable sharing."><form onSubmit={submit}><div className="form-grid"><Field label="Full name" value={form.name} onChange={v=>upd('name',v)} required/><Field label="Email address" type="email" value={form.email} onChange={v=>upd('email',v)}/><SelectField label="Preferred professional" value={form.professional} onChange={v=>upd('professional',v)} options={['No preference','Psychiatrist','Registered Psychologist (RPsy)','Registered Psychometrician (RPm)','Guidance Counselor']}/><SelectField label="Consultation type" value={form.type} onChange={v=>upd('type',v)} options={['Individual counseling','Relationship counseling','Personal development']}/><Field label="Preferred date" type="date" value={form.date} onChange={v=>upd('date',v)} required/><Field label="Preferred time" type="time" value={form.time} onChange={v=>upd('time',v)} required/><SelectField label="Session format" value={form.format} onChange={v=>upd('format',v)} options={['Online','In person','Not sure yet']}/></div><TextArea label="What would you like us to know? (optional)" value={form.reason} onChange={v=>upd('reason',v)} placeholder="Share a short note if you wish…"/><button className="btn btn-primary">Send appointment request <Send size={16}/></button>{msg&&<p className="form-message">{msg}</p>}</form></FormLayout>}
function FormLayout({tag,title,intro,children}){return <section className="section form-layout"><div className="form-heading"><Eyebrow>{tag}</Eyebrow><h1>{title}</h1><p>{intro}</p></div><div className="form-card wide">{children}</div></section>}

function Assessment({followUp=false}){
 const [values,setValues]=useState({});
 const [msg,setMsg]=useState('');
 const [saving,setSaving]=useState(false);
 const upd=(key,value)=>setValues(prev=>({...prev,[key]:value}));
 const toggle=(key,value)=>upd(key,(values[key]||[]).includes(value)?(values[key]||[]).filter(item=>item!==value):[...(values[key]||[]),value]);
 const initialQuestions=[
  ['1. How have you been feeling lately?','mood',['Mostly happy or content','Calm and emotionally stable','Sometimes stressed or overwhelmed','Frequently sad or anxious','Emotionally exhausted',"Unsure how I'm feeling"]],
  ['2. How often have you experienced emotional distress recently?','frequency',['Never','Rarely','Sometimes','Often','Almost every day']],
  ['3. Have you noticed any changes in your daily habits or emotional state?','habits',['Yes, significant changes','Yes, slight changes','No noticeable changes',"I'm not sure"]],
  ['6. How long have you been experiencing these concerns?','duration',['Less than a week','A few weeks','1–3 months','3–6 months','More than six months','Unsure / Prefer not to say']],
  ['7. How have your current concerns affected your daily life?','impact',['They have not affected my daily activities.','They occasionally affect my concentration or productivity.','They make it difficult to complete some daily responsibilities.','They significantly affect my relationships or daily routine.','They make it difficult for me to manage everyday activities.']],
  ['8. How would you rate your ability to manage your emotions lately?','management',['Very good','Good','Moderate','Difficult','Very difficult','Unsure']],
  ['9. Have you previously consulted a mental health professional?','prior',['Yes, currently receiving support.','Yes, in the past.','No, this would be my first consultation.','Prefer not to say.']]
 ];
 const followQuestions=[
  ['1. How have you been feeling since your last counseling session?','progress',['Much better','A little better','Still the same','I have been having a difficult time']],
  ['2. How well have you been managing your emotions?','emotion_management',['Very well','Fairly well','Sometimes I struggle','I find it difficult']],
  ['3. Have you applied anything you learned during your counseling session?','applied',['Yes, consistently','Yes, a few times','I tried, but struggled','Not yet']],
  ['4. What activity have you tried to support your emotional well-being?','activity',['Journaling or writing my thoughts','Breathing exercises or meditation','Drawing, music, or other creative activities','Walking or spending time outdoors']],
  ['5. How often have you practiced activities that help you relax?','relaxation',['Every day','Several times a week','Once in a while','Not yet']],
  ['6. Have you noticed any changes in how you handle personal challenges?','challenges',['Yes, I handle them better','Yes, but only in some situations','Not much has changed',"I'm still figuring things out"]],
  ['7. How comfortable are you expressing your thoughts and feelings?','comfort',['Very comfortable','Somewhat comfortable','I still find it difficult','I am not comfortable yet']],
  ['8. What area would you like to continue working on?','focus',['Emotional management','Self-confidence','Relationships and communication','Stress management and self-care']],
  ['9. What personal activity or goal would you like to accomplish before your next session?','goal',['Maintain a daily journal','Practice relaxation exercises','Spend time on a hobby I enjoy','Build a healthy daily routine']],
  ['10. What best describes your progress since your last counseling session?','overall',['I have made meaningful progress','I have made small steps forward','I am still learning and adjusting','I need more guidance and support']]
 ];
 const concerns=['Academic or work-related concerns','Family concerns','Relationship or social concerns','Financial difficulties','Personal expectations or self-esteem','Emotional or mental well-being','Other','Prefer not to say'];
 const coping=['Talk to friends or family.','Spend time alone.','Engage in hobbies or recreational activities.','Exercise or participate in physical activities.','Practice relaxation or mindfulness.','Seek professional support.',"I usually don't know how to cope.",'Other'];
 async function submit(e){
  e.preventDefault();setMsg('');
  if(!supabase){setMsg('Assessment service is unavailable. Please try again later.');return;}
  setSaving(true);
  try{
   const {data:{user}}=await supabase.auth.getUser();
   if(!user){setMsg('Please sign in before saving an assessment.');return;}
   const {error}=await supabase.from('assessments').insert({user_id:user.id,assessment_type:followUp?'follow_up':'initial',responses:values});
   if(error)throw error;
   setMsg(followUp?'Your post-counseling reflection has been saved.':'Your initial assessment has been saved. You may now continue to the appointment form.');
  }catch(error){setMsg(error.message||'We could not save your responses. Please try again.');}
  finally{setSaving(false);}
 }
 const questions=followUp?followQuestions:initialQuestions;
 const radioQuestion=([label,key,options])=><fieldset className="assessment-question" key={key}><legend>{label}</legend><div className="assessment-options">{options.map(option=><label className="assessment-option" key={option}><input type="radio" name={key} value={option} checked={values[key]===option} onChange={()=>upd(key,option)} required/><span>{option}</span></label>)}</div></fieldset>;
 const multiQuestion=(label,key,options)=><fieldset className="assessment-question" key={key}><legend>{label}</legend><p className="question-hint">Multiple selections allowed.</p><div className="assessment-options">{options.map(option=><label className="assessment-option" key={option}><input type="checkbox" checked={(values[key]||[]).includes(option)} onChange={()=>toggle(key,option)}/><span>{option}</span></label>)}</div>{(values[key]||[]).includes('Other')&&<label className="field other-answer"><span>Please specify</span><input value={values[key+'_other']||''} onChange={e=>upd(key+'_other',e.target.value)} placeholder="Write your answer"/></label>}</fieldset>;
 return <FormLayout tag={followUp?'TAKIPSILIM · AFTER THE LIGHT SESSION':'BUKANG LIWAYWAY · BEFORE THE LIGHT SESSION'} title={followUp?'Reflect on your journey since the last session.':'A gentle check-in before your session.'} intro={followUp?'Answer each question based on your experience after your most recent counseling session. Select only one answer per question. There are no right or wrong answers. Please answer honestly based on your personal experience.':'Complete this initial assessment and emotional check-in to help your therapist understand your current feelings, personal concerns, and the kind of support you need. Take your time and share only what you feel comfortable sharing.'}>
  <form className="assessment-form" onSubmit={submit}>
   {!followUp&&<div className="assessment-instructions"><b>Before you begin</b><p>This check-in is intended to help you reflect on your current feelings and concerns. It is not a professional diagnosis.</p></div>}
   {followUp&&<div className="assessment-instructions"><b>Instructions</b><p>Answer based on your experience after your most recent counseling session. Select one answer per question.</p></div>}
   {followUp?questions.map(radioQuestion):<>{questions.slice(0,3).map(radioQuestion)}{multiQuestion('4. What areas of your life are currently causing you concern?','concerns',concerns)}<div className="assessment-question"><label className="field"><span>5. Would you like to share what has been bothering you recently? (Optional)</span><textarea rows="4" value={values.share||''} onChange={e=>upd('share',e.target.value)} placeholder="You may share anything you feel comfortable expressing…"/></label></div>{questions.slice(3).map(radioQuestion)}{multiQuestion("10. What do you usually do when you're feeling emotionally overwhelmed?",'coping',coping)}</>}
   {followUp&&<>
    <section className="assessment-subsection"><h2>Post-Session Reflection</h2><p>Take a moment to reflect on your counseling experience.</p>
     {[['What is the most important thing you learned from your counseling session?','reflection_learning'],['What realization did you have about yourself?','reflection_realization'],['Was there anything you wanted to share but were unable to discuss?','reflection_unshared'],['What thoughts or concerns are still on your mind?','reflection_concerns']].map(([label,key])=><label className="field" key={key}><span>{label}</span><textarea rows="3" value={values[key]||''} onChange={e=>upd(key,e.target.value)}/></label>)}
    </section>
    <section className="assessment-subsection"><h2>Therapeutic Activities</h2><p>Choose an activity that feels right for you today. Go at your own pace, and return whenever you need.</p>
     <div className="activity-card"><h3>1. Journaling</h3><p>Express your thoughts and feelings through writing.</p><ul><li>What has been on your mind lately?</li><li>What emotions have you been experiencing?</li><li>What is one thing you wish you could tell someone?</li></ul><label className="field"><span>Journal writing area</span><textarea rows="4" value={values.activity_journal||''} onChange={e=>upd('activity_journal',e.target.value)} placeholder="Write freely…"/></label></div>
     <div className="activity-card"><h3>2. Breathing Exercise</h3><p>Give yourself a moment to pause and focus on your breathing.</p><ol><li>Find a comfortable position.</li><li>Slowly breathe in, then gently breathe out.</li><li>Repeat for a few moments and notice how you feel.</li></ol><label className="field"><span>Breathing exercise reflection (optional)</span><textarea rows="2" value={values.activity_breathing||''} onChange={e=>upd('activity_breathing',e.target.value)} placeholder="How did the exercise feel?"/></label></div>
     <div className="activity-card"><h3>3. Emotional Awareness</h3><p>Recognize and understand your current emotions.</p><ul><li>What emotion are you feeling right now?</li><li>What might have caused you to feel this way?</li><li>What do you need at this moment?</li></ul><label className="field"><span>Your reflection</span><textarea rows="3" value={values.activity_emotions||''} onChange={e=>upd('activity_emotions',e.target.value)}/></label></div>
     <div className="activity-card"><h3>4. Thought Reflection</h3><p>Explore your thoughts and consider different perspectives.</p><ul><li>What thought has been bothering you lately?</li><li>What makes you think this way?</li><li>Is there another way you can look at the situation?</li></ul><label className="field"><span>Your reflection</span><textarea rows="3" value={values.activity_thoughts||''} onChange={e=>upd('activity_thoughts',e.target.value)}/></label></div>
    </section>
    <section className="assessment-subsection"><h2>Next Session Preparation</h2><p>Keep track of your experiences and concerns before your next counseling session.</p>
     {[['My Progress','What improvements or positive changes have you noticed?','next_progress'],['Ongoing Challenges','What difficulties are you still experiencing?','next_challenges'],['Topics to Discuss','What would you like to talk about with your counselor?','next_topics']].map(([heading,label,key])=><label className="field" key={key}><span><b>{heading}</b> — {label}</span><textarea rows="3" value={values[key]||''} onChange={e=>upd(key,e.target.value)}/></label>)}
    </section>
   </>}
   <label className="checkline assessment-ack"><input type="checkbox" required/><span>I understand that this form is for reflection and does not provide a professional diagnosis or emergency support.</span></label>
   <button className="btn btn-primary" type="submit" disabled={saving}>{saving?'Saving…':followUp?'Save Progress':'Save Assessment'} <Send size={16}/></button>
   {msg&&<p className="form-message" role="status">{msg}</p>}
   {!followUp&&<p className="assessment-next">After completing Bukang Liwayway, continue to the separate <Link to="/appointment">Appointment Form</Link> to request a session.</p>}
  </form>
 </FormLayout>;
}

function EventRegister(){
 const [params]=useSearchParams();const eventId=params.get('event')||'';
 const [name,setName]=useState(''),[email,setEmail]=useState(''),[notes,setNotes]=useState(''),[msg,setMsg]=useState('');
 async function submit(e){e.preventDefault();if(!supabase){setMsg('Event registration is unavailable.');return;}const {data:{user}}=await supabase.auth.getUser();if(!user){setMsg('Please sign in before registering for an event.');return;}if(!eventId){setMsg('Please choose an event from the calendar first.');return;}const {error}=await supabase.from('event_registrations').insert({event_id:eventId,user_id:user.id,attendee_name:name,attendee_email:email,notes});setMsg(error?error.message:'Your event registration has been saved.');}
 return <FormLayout tag="EVENT REGISTRATION" title="Save your place." intro="Complete the details below to register for a Liwayway activity."><form onSubmit={submit}><Field label="Your name" value={name} onChange={setName} required/><Field label="Email address" type="email" value={email} onChange={setEmail} required/><TextArea label="Optional note" value={notes} onChange={setNotes} placeholder="Anything you would like the organizers to know…"/><button className="btn btn-primary">Register for event <ArrowRight size={16}/></button>{msg&&<p className="form-message">{msg}</p>}</form></FormLayout>;
}
function Admin(){
 const [user,setUser]=useState(null),[data,setData]=useState({}),[msg,setMsg]=useState('');
 useEffect(()=>{if(!supabase)return;supabase.auth.getUser().then(async({data:{user:u}})=>{setUser(u);if(u?.app_metadata?.role==='admin'){const names=['appointments','assessments','event_registrations','feedback','contact_messages'];const results=await Promise.all(names.map(n=>supabase.from(n).select('*').order('created_at',{ascending:false}).limit(100)));const out={};results.forEach((r,i)=>{if(r.error)setMsg(r.error.message);else out[names[i]]=r.data||[]});setData(out);}});},[]);
 if(!user)return <section className="section"><Eyebrow>LIWAYWAY ADMIN</Eyebrow><h1>Sign in to continue.</h1><Link className="btn btn-primary" to="/login">Sign in</Link></section>;
 if(user.app_metadata?.role!=='admin')return <section className="section"><Eyebrow>LIWAYWAY ADMIN</Eyebrow><h1>Admin access is restricted.</h1><p>This account has not been assigned the trusted admin role.</p></section>;
 return <section className="section dashboard"><Eyebrow>LIWAYWAY ADMIN</Eyebrow><h1>Project <em>overview.</em></h1>{msg&&<p className="form-message">{msg}</p>}{Object.entries(data).map(([k,v])=><div className="admin-table"><h2>{k.replace('_',' ')} <small>{v.length}</small></h2>{v.map(row=><div className="appointment-row"><b>{row.preferred_name||row.attendee_name||row.display_name||row.name||row.title||row.assessment_type||row.email||'Record'}</b><span>{row.status||row.created_at?.slice(0,10)||'Submitted'}</span></div>)}</div>)}</section>;
}

function Feedback(){const[rating,setRating]=useState('5'),[comment,setComment]=useState(''),[name,setName]=useState(''),[msg,setMsg]=useState('');async function submit(e){e.preventDefault();if(!supabase){setMsg('Feedback is not connected at the moment. Please email liwaywaycounseling@gmail.com.');return;}const{data:{user}}=await supabase.auth.getUser();if(!user){setMsg('Please sign in before submitting feedback.');return;}const{error}=await supabase.from('feedback').insert({user_id:user.id,display_name:name,rating:Number(rating),message:comment});setMsg(error?error.message:'Thank you for sharing your feedback.');}return <FormLayout tag="LIWAYWAY REVIEWS" title="Your thoughts help us grow." intro="Share a voluntary note about your experience with the Liwayway website."><form onSubmit={submit}><Field label="Name (optional)" value={name} onChange={setName}/><SelectField label="Your rating" value={rating} onChange={setRating} options={['5','4','3','2','1']}/><TextArea label="Your feedback" value={comment} onChange={setComment} placeholder="What felt helpful? What could be clearer?"/><button className="btn btn-primary">Submit feedback <Send size={16}/></button>{msg&&<p className="form-message">{msg}</p>}</form></FormLayout>}
function Journal(){
 const[title,setTitle]=useState(''),[body,setBody]=useState(''),[entries,setEntries]=useState([]),[msg,setMsg]=useState(''),[editing,setEditing]=useState(null),[prompt,setPrompt]=useState('');
 const prompts=[
  'What is one feeling that has been present for you today? What might it be trying to tell you?',
  'Describe a small moment today that brought you comfort, relief, or joy.',
  'What has been weighing on your mind lately? Write about it without judging yourself.',
  'What is something you wish others understood about what you are experiencing?',
  'When did you feel most like yourself recently? What made that moment different?',
  'What is one thing you can give yourself permission to let go of today?',
  'What would you say to a friend who was going through the same thing you are?',
  'Name three things you appreciate about yourself, even if they feel small.',
  'What is one challenge you faced recently, and what helped you get through it?',
  'What do you need more of right now: rest, connection, patience, courage, or something else?'
 ];
 useEffect(()=>{if(supabase)supabase.from('journal_entries').select('*').order('created_at',{ascending:false}).then(({data})=>{if(data)setEntries(data)});},[]);
 function generatePrompt(){let next=prompts[Math.floor(Math.random()*prompts.length)];if(next===prompt)next=prompts[(prompts.indexOf(next)+1)%prompts.length];setPrompt(next);}
 function usePrompt(){if(prompt)setBody(current=>current?current+'\n\n'+prompt+'\n':prompt+'\n');}
 async function save(e){e.preventDefault();if(!supabase){setMsg('Journal storage is not connected.');return;}const{data:{user}}=await supabase.auth.getUser();if(!user){setMsg('Please sign in to use your private journal.');return;}const{data,error}=await supabase.from('journal_entries').insert({user_id:user.id,title,entry:body}).select().single();if(error)setMsg(error.message);else{setEntries(p=>[data,...p]);setTitle('');setBody('');setPrompt('');setMsg('Your entry has been saved.');}}
 function beginEdit(e){setEditing(e.id);setTitle(e.title||'');setBody(e.entry||'');setMsg('');}
 async function saveEdit(e){e.preventDefault();const{data,error}=await supabase.from('journal_entries').update({title,entry:body,updated_at:new Date().toISOString()}).eq('id',editing).select().single();if(error)setMsg(error.message);else{setEntries(p=>p.map(x=>x.id===editing?data:x));setEditing(null);setTitle('');setBody('');setPrompt('');setMsg('Your changes have been saved.');}}
 async function removeEntry(id){const{error}=await supabase.from('journal_entries').delete().eq('id',id);if(error)setMsg(error.message);else{setEntries(p=>p.filter(x=>x.id!==id));setMsg('Entry deleted.');}}
 return <><PageHero tag="TALA AT SALOOBIN" title={<>A quiet corner for your <em>thoughts.</em></>} text="Write freely, at your own pace. Your journal is intended for your personal reflection."/><section className="section journal-layout"><form className="form-card" onSubmit={editing?saveEdit:save}><Eyebrow>{editing?'EDIT JOURNAL ENTRY':'NEW JOURNAL ENTRY'}</Eyebrow><h2>{editing?'Revisit your words.':'What is on your mind?'}</h2><Field label="Entry title" value={title} onChange={setTitle} required/><div className="journal-prompt-tools"><div><Eyebrow>NEED A PLACE TO START?</Eyebrow><p>Generate a gentle writing prompt whenever you need a little inspiration.</p></div><button className="btn btn-outline" type="button" onClick={generatePrompt}><Sparkles size={15}/> Generate a prompt</button></div>{prompt&&<div className="journal-prompt"><b>Your writing prompt</b><p>{prompt}</p><button className="btn btn-outline" type="button" onClick={usePrompt}>Use this prompt</button></div>}<TextArea label="Your thoughts" value={body} onChange={setBody} placeholder="Start wherever you are…"/><button className="btn btn-primary">{editing?'Save changes':'Save entry'} <NotebookPen size={16}/></button>{editing&&<button className="btn btn-quiet" type="button" onClick={()=>{setEditing(null);setTitle('');setBody('');setPrompt('');}}>Cancel edit</button>}{msg&&<p className="form-message">{msg}</p>}</form><div className="journal-entries"><Eyebrow>YOUR REFLECTIONS</Eyebrow><h2>Entries saved</h2>{entries.length?entries.map(e=><article className="journal-entry" key={e.id}><small>{new Date(e.created_at).toLocaleDateString()}</small><h3>{e.title}</h3><p>{e.entry}</p><div className="journal-actions"><button className="btn btn-outline" type="button" onClick={()=>beginEdit(e)}>Edit</button><button className="btn btn-quiet" type="button" onClick={()=>removeEntry(e.id)}>Delete</button></div></article>):<div className="empty-state"><NotebookPen/><p>Your saved entries will appear here after you sign in.</p></div>}</div></section></>}
function Dashboard(){
 const[user,setUser]=useState(null),[appointments,setAppointments]=useState([]),[assessments,setAssessments]=useState([]),[journals,setJournals]=useState([]),[registrations,setRegistrations]=useState([]),[msg,setMsg]=useState('');
 useEffect(()=>{let active=true;if(!supabase)return;supabase.auth.getUser().then(async({data,error})=>{
  if(!active)return;if(error){setMsg(error.message);return;}const current=data.user;setUser(current);if(!current)return;
  const results=await Promise.all([
   supabase.from('appointments').select('*').eq('user_id',current.id).order('created_at',{ascending:false}),
   supabase.from('assessments').select('id,assessment_type,created_at').eq('user_id',current.id).order('created_at',{ascending:false}),
   supabase.from('journal_entries').select('id,title,created_at').eq('user_id',current.id).order('created_at',{ascending:false}).limit(5),
   supabase.from('event_registrations').select('id,event_id,created_at').eq('user_id',current.id).order('created_at',{ascending:false})
  ]);
  if(!active)return;
  if(results[0].data)setAppointments(results[0].data);
  if(results[1].data)setAssessments(results[1].data);
  if(results[2].data)setJournals(results[2].data);
  if(results[3].data)setRegistrations(results[3].data);
  const failed=results.find(x=>x.error);if(failed)setMsg('Some account history could not be loaded. You can still use the forms below.');
 });return()=>{active=false};},[]);
 async function logout(){await supabase?.auth.signOut();setUser(null);}
 const dateLabel=value=>value?new Date(value).toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'}):'Date unavailable';
 return <section className="section dashboard"><Eyebrow>YOUR LIWAYWAY SPACE</Eyebrow><h1>A little space for <em>you.</em></h1>{!user?<div className="empty-state"><LogIn/><p>Please sign in to view your personal Liwayway Space, forms, and saved records.</p><Link className="btn btn-primary" to="/login">Sign in</Link><p>New here? <Link to="/register">Create an account</Link></p></div>:<>
  <div className="dashboard-top"><p>Signed in as <b>{user.email}</b></p><button className="btn btn-outline" onClick={logout}><LogOut size={16}/> Sign out</button></div>
  <div className="dashboard-section-heading"><Eyebrow>YOUR LIWAYWAY TOOLS</Eyebrow><h2>Your forms and personal space</h2><p>Access the forms and resources you need throughout your Liwayway journey.</p></div>
  <div className="dashboard-cards">
   <Link to="/assessment"><ClipboardList/><b>Initial Assessment</b><span>Complete your emotional check-in and share your concerns before counseling</span></Link>
   <Link to="/appointment"><CalendarDays/><b>Appointment Form</b><span>Choose your preferred professional, consultation type, date, and format</span></Link>
   <Link to="/follow-up"><ClipboardList/><b>Post-Counseling Assessment</b><span>Reflect on your counseling experience, learnings, coping, progress, and next steps</span></Link>
   <Link to="/journal"><NotebookPen/><b>Tala at Saloobin Journal</b><span>Write privately, use optional writing prompts, and manage your saved entries</span></Link>
   <Link to="/privacy"><ShieldCheck/><b>Privacy Notice &amp; Informed Consent</b><span>Review how your information is handled</span></Link>
   <Link to="/events"><Users/><b>Events &amp; Lightalk</b><span>Explore community events and webinar sessions</span></Link>
  </div>
  <div className="dashboard-section-heading"><Eyebrow>YOUR RECORDS</Eyebrow><h2>Personal activity and history</h2></div>
  <div className="dashboard-history-grid">
   <div className="dashboard-history"><h3>Appointment requests</h3>{appointments.length?appointments.map(a=><div className="appointment-row" key={a.id}><b>{a.consultation_type||'Counseling appointment'} · {a.preferred_date||'Date to be confirmed'}</b><span>{a.status||'Pending'}</span></div>):<p className="muted">No appointment requests yet.</p>}</div>
   <div className="dashboard-history"><h3>Assessment history</h3>{assessments.length?assessments.map(a=><div className="appointment-row" key={a.id}><b>{a.assessment_type==='follow_up'?'Post-Counseling Assessment':'Initial Assessment'}</b><span>{dateLabel(a.created_at)}</span></div>):<p className="muted">No saved assessments yet.</p>}</div>
   <div className="dashboard-history"><h3>Journal entries</h3>{journals.length?journals.map(j=><div className="appointment-row" key={j.id}><b>{j.title||'Untitled reflection'}</b><span>{dateLabel(j.created_at)}</span></div>):<p className="muted">No saved journal entries yet.</p>}<Link className="text-link" to="/journal">Open journal <ArrowRight size={15}/></Link></div>
   <div className="dashboard-history"><h3>Event registrations</h3>{registrations.length?registrations.map(x=><div className="appointment-row" key={x.id}><b>Community event registration</b><span>{dateLabel(x.created_at)}</span></div>):<p className="muted">No event registrations yet.</p>}<Link className="text-link" to="/events">Explore events <ArrowRight size={15}/></Link></div>
  </div>
  <div className="dashboard-bottom-links"><Link to="/feedback">Share feedback</Link><Link to="/contact">Contact Liwayway</Link><Link to="/faq">Frequently asked questions</Link></div>
  {msg&&<p className="form-message" role="status">{msg}</p>}
 </>}</section>;
}

function FAQ(){const faqs=[['ABOUT LIWAYWAY','What is Liwayway?',"Liwayway is an online mental health platform designed to connect individuals with mental health professionals, counseling services, and helpful resources. It aims to provide accessible information and support for individuals seeking to understand and improve their emotional well-being."],['ABOUT LIWAYWAY','Who can use the Liwayway platform?',"Individuals seeking mental health information, emotional support, or professional counseling may explore the available services. Users are encouraged to review the requirements and availability of each service before proceeding."],['ABOUT LIWAYWAY','What services does Liwayway offer?',"Bukang Liwayway provides an initial assessment and emotional check-in before counseling. Liwanag ng Araw describes the main counseling service. Takipsilim provides post-counseling reflection, follow-up assessments, and therapeutic activities. Tala at Saloobin is a personal digital journal. Lightalk provides online talks and webinars, while Kapwa focuses on community support and outreach."],['ACCOUNT REGISTRATION','How can I create an account?',"Visit the registration page, provide the required information, review the Privacy Notice and Informed Consent, and follow the instructions to complete your account setup."],['ACCOUNT REGISTRATION','How can I access my account?',"Enter your registered email address and password on the login page to access your account and personal features."],['ACCOUNT REGISTRATION','What should I do if I forget my password?',"Use the password recovery option provided by the sign-in service, if available. If you cannot access your account, contact the Liwayway team through the contact information on the website."],['COUNSELING SERVICES','How do I complete the initial assessment?',"Visit Bukang Liwayway and complete the Initial Assessment and Emotional Check-in. Your responses provide an overview of your current concerns and may help identify the type of support you need. The assessment is not a professional diagnosis."],['COUNSELING SERVICES','How can I choose a counselor?',"Browse the profiles of available mental health professionals to learn about their qualifications, professional credentials, and areas of specialization. You may select a professional whose background and services align with your needs, or choose no preference where available."],['COUNSELING SERVICES','How can I book a counseling session?',"After completing the initial assessment, visit the separate Appointment Form. Select your preferred professional, consultation type, date, time, and format, then submit your request. Your requested schedule is subject to availability and confirmation."],['COUNSELING SERVICES','Can I reschedule or cancel my counseling appointment?',"If you need to reschedule or cancel, contact the team through the communication channels provided and follow the appointment policies. Please notify the team as early as possible."],['COUNSELING SERVICES','Are counseling sessions confidential?',"Information shared during counseling should be handled in accordance with applicable data privacy requirements and professional ethical standards. Confidentiality may have limitations in certain circumstances, such as safety concerns or legal requirements. Clients should be informed of these limitations through the informed consent process."],['OTHER SERVICES','What is Tala at Saloobin?',"Tala at Saloobin is a personal digital journaling space where you can write about your thoughts, feelings, and everyday experiences. You may use guided prompts or write freely at your own pace."],['OTHER SERVICES','What is Takipsilim used for?',"Takipsilim provides post-counseling activities that encourage reflection and continued personal growth. These may include follow-up assessments, therapeutic activities recommended by a counselor, coping-strategy practice, and progress monitoring."],['OTHER SERVICES','How can I participate in Lightalk?',"Visit the Lightalk section to explore upcoming online talks, webinars, and discussions. Choose an event that interests you and follow its registration process."],['OTHER SERVICES',"How can I participate in Kapwa's community initiatives?","Explore the Kapwa section to learn about community support activities, mental health workshops, volunteer opportunities, and donation initiatives. Participation details may be announced through the platform or by contacting the team."],['PRIVACY AND SUPPORT','How is my personal information protected?',"Liwayway recognizes the importance of protecting personal information, especially information related to mental health. Personal data should be collected and processed only for legitimate, explained purposes and handled with appropriate safeguards. Read the Privacy Notice to understand what information may be collected, how it is used, and what choices are available to you."],['PRIVACY AND SUPPORT','What should I do if I need further assistance?',"For questions or concerns about the website, registration, or appointment requests, contact the team using the contact information provided. For urgent mental health support, use the crisis resources listed on the website; this platform is not an emergency service."],['REVIEWS AND FEEDBACK','What is the Liwayway Reviews section?',"The Reviews section allows visitors to read shared experiences and feedback and provides an opportunity for users to share thoughts that may help improve the platform."],['REVIEWS AND FEEDBACK','How can I share my experience?',"Visit the Reviews section, choose the available ratings or feedback option, and follow the instructions to submit your review."],['REVIEWS AND FEEDBACK','Is sharing a review required?',"No. Sharing your experience is completely voluntary. You may choose whether or not to submit a rating or written feedback."],['REVIEWS AND FEEDBACK','Can I share suggestions or concerns about Liwayway?',"Yes. Suggestions, comments, and constructive feedback are welcome and may help improve the website and the experience it provides."]];let current='';let n=0;return <><PageHero tag="FREQUENTLY ASKED QUESTIONS" title={<>A few things you might be <em>wondering.</em></>} text="Find answers about Liwayway, creating an account, counseling services, the different features, privacy, and ways to connect."/><section className="section faq-list">{faqs.map(([category,q,answer])=><React.Fragment key={q}>{current!==category?(current=category,<h2 className="faq-category">{category}</h2>):null}<details><summary>{++n}. {q}<ChevronRight/></summary><p>{answer}</p></details></React.Fragment>)}<p>Still have questions? We're here to help you navigate your mental health journey.</p><Link className="text-link" to="/contact">Contact Us <ArrowRight size={16}/></Link></section></>}
function Privacy(){return <><PageHero tag="DATA PRIVACY AND CONSENT" title={<>Your story deserves <em>care and respect.</em></>} text="Please read this Privacy Notice and Informed Consent before creating an account, completing an assessment, requesting an appointment, or using personal features. It explains what information you may provide and how it is intended to be handled."/><section className="section privacy-copy"><h2>1. Purpose of collection</h2><p>Liwayway may collect information you voluntarily provide so the website can support account registration, initial and follow-up assessments, appointment requests, event registration, journal features, feedback, and contact inquiries. Information should be used only for the purpose explained at the point of collection and for operating, maintaining, and improving the website.</p><h2>2. Information that may be collected</h2><p>Depending on the feature you use, information may include your name, school email address, account credentials, appointment preferences, event registration details, messages, feedback, journal entries, and answers about your feelings, emotional well-being, personal concerns, coping strategies, and experiences after a counseling session. Some assessment responses may be sensitive personal information.</p><h2>3. How information is used</h2><p>Information may be used to create and manage your account, receive and review appointment requests, save assessment responses, provide access to your journal entries, manage event registrations, respond to inquiries, and maintain the website's functions. Information should not be used for unrelated purposes without an appropriate basis and notice.</p><h2>4. Storage and access</h2><p>Information submitted through connected account features may be stored in the website's database. Access to account-related records is intended to be limited through sign-in requirements and database access controls. Do not share your password. Sign out when using a shared device. Avoid entering unnecessary identifying or highly sensitive details in optional fields.</p><h2>5. Confidentiality and its limitations</h2><p>Information related to counseling and mental health should be treated with care. Confidentiality may have limits in situations involving serious safety concerns, safeguarding responsibilities, or legal requirements. Any actual counseling service must explain its own confidentiality terms and limits through a separate informed consent process before a session.</p><h2>6. Retention and deletion</h2><p>Information should be kept only for as long as needed for the stated purpose, applicable requirements, and legitimate record-keeping needs. If you want to request access, correction, or deletion of information associated with your account, contact the Liwayway team. Some records may need to be retained where required by law or for legitimate security and administrative purposes.</p><h2>7. Your choices and rights</h2><p>You may choose not to provide optional information. You may ask what personal information is held about you and request correction or deletion, subject to applicable requirements and technical limitations. You may also withdraw consent for future optional processing by contacting the team; withdrawal does not automatically undo processing already carried out lawfully.</p><h2>8. Security</h2><p>Reasonable technical and organizational safeguards should be used to protect information from unauthorized access, disclosure, alteration, or loss. No website or method of electronic storage can be guaranteed completely secure. Please use a strong password and access your account from a trusted device.</p><h2>9. Children and emergency situations</h2><p>If you are under 18, please involve a parent, guardian, or appropriate trusted adult before submitting sensitive information or requesting services. This website is not an emergency response service and is not monitored as a crisis hotline. If you or someone else is in immediate danger, contact local emergency services or the NCMH Crisis Hotline at 1553 or 1800-1888-1553.</p><h2>10. Contact</h2><p>For questions about this notice or a request concerning your information, contact <a href="mailto:liwaywaycounseling@gmail.com">liwaywaycounseling@gmail.com</a>.</p><div className="privacy-consent"><h2>Privacy acknowledgment and informed consent</h2><p>By proceeding, you acknowledge that you have read and understood this Privacy Notice and voluntarily agree to provide the information necessary for the feature you choose to use. You understand that assessment forms are reflective tools and are not a professional diagnosis or emergency service.</p><p><b>Your privacy matters. Your journey begins with understanding.</b></p></div><p className="muted">This notice describes the intended handling of information on this website. It is not a substitute for a formal institutional privacy review or service-specific clinical informed consent. Your instructor or institution should review and approve the final notice before the website is used to collect real participants' sensitive information.</p></section></>}
function Contact(){const[name,setName]=useState(''),[email,setEmail]=useState(''),[message,setMessage]=useState(''),[status,setStatus]=useState('');async function submit(e){e.preventDefault();if(!supabase){setStatus('Please email liwaywaycounseling@gmail.com to reach the project team.');return;}const{error}=await supabase.from('contact_messages').insert({name,email,message});setStatus(error?error.message:'Your message has been submitted. Thank you.');}return <><PageHero tag="CONTACT" title={<>A hello can be the <em>beginning.</em></>} text="Questions, suggestions, or a little feedback? We would be glad to hear from you."/><section className="section contact-grid"><div><h2>Reach out, whenever you're ready.</h2><div className="contact-line"><Mail/><div><b>Email</b><a href="mailto:liwaywaycounseling@gmail.com">liwaywaycounseling@gmail.com</a></div></div><div className="contact-line"><Phone/><div><b>Telephone</b><span>2222</span></div></div><div className="contact-line"><MapPin/><div><b>Office</b><span>OLFU PTRB, Quezon City</span></div></div><div className="crisis-note"><b>Need urgent support?</b><p>NCMH Crisis Hotline: 1553 or 1800-1888-1553</p></div></div><form className="form-card" onSubmit={submit}><Eyebrow>SEND A MESSAGE</Eyebrow><Field label="Your name" value={name} onChange={setName} required/><Field label="Email address" type="email" value={email} onChange={setEmail} required/><TextArea label="Message" value={message} onChange={setMessage} placeholder="Write your message…" /><button className="btn btn-primary">Send message <Send size={16}/></button>{status&&<p className="form-message">{status}</p>}</form></section></>}
function NotFound(){return <section className="section not-found"><Sun size={50}/><h1>Let's find the right path.</h1><p>This page may have moved.</p><Link className="btn btn-primary" to="/">Back to home</Link></section>}
function App(){return <BrowserRouter><Shell><Routes><Route path="/" element={<Home/>}/><Route path="/about" element={<About/>}/><Route path="/behind" element={<Behind/>}/><Route path="/services" element={<Services/>}/><Route path="/shared" element={<Shared/>}/><Route path="/steps" element={<Steps/>}/><Route path="/events" element={<Events/>}/><Route path="/login" element={<AuthForm/>}/><Route path="/register" element={<AuthForm mode="register"/>}/><Route path="/appointment" element={<Appointment/>}/><Route path="/assessment" element={<Assessment/>}/><Route path="/follow-up" element={<Assessment followUp/>}/><Route path="/admin" element={<Admin/>}/><Route path="/journal" element={<Journal/>}/><Route path="/dashboard" element={<Dashboard/>}/><Route path="/feedback" element={<Feedback/>}/><Route path="/event-register" element={<EventRegister/>}/><Route path="/faq" element={<FAQ/>}/><Route path="/privacy" element={<Privacy/>}/><Route path="/contact" element={<Contact/>}/><Route path="*" element={<NotFound/>}/></Routes></Shell></BrowserRouter>}
createRoot(document.getElementById('root')).render(<App/>);
